def count_element_freq(mixed_tuple):
    """
    Counts the frequency of each unique element in a nested tuple.

    Parameters:
    mixed_tuple (tuple): A nested tuple containing various types of elements.

    Returns:
    dict: A dictionary with elements as keys and their respective frequencies as values.

    Examples:
    count_element_freq((5, 6, (5, 6), 7, (8, 9), 9)) == {5: 2, 6: 2, 7: 1, 8: 1, 9: 2}
    """
    frequency_dict = {}
    for item in mixed_tuple:
        if isinstance(item, tuple):
            for subitem in item:
                if subitem in frequency_dict:
                    frequency_dict[subitem] += 1
                else:
                    frequency_dict[subitem] = 1
        else:
            if item in frequency_dict:
                frequency_dict[item] += 1
            else:
                frequency_dict[item] = 1
    return frequency_dict

