    n = len(s1)
    m = len(s2)

    # Create a table to store the minimum swaps needed
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and first column
    for i in range(1, n + 1):
        dp[i][0] = i - 1

    for j in range(1, m + 1):
        dp[0][j] = j - 1

    # Fill the table using the relationship dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1

    # The value in dp[n][m] will be the minimum swaps needed
    return dp[n][m]

