    min_val = nums[0]
    max_val = nums[-1]
    count = 0

    for num in nums:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num

        if max_val - min_val <= k:
            count += 1
            min_val = num + 1
            max_val = nums[-1]

    return count

