    # Initialize variables to store the product of even and odd numbers
    even_product = 1
    odd_product = 1

    # Flag to check if there is at least one even or odd number
    has_even = has_odd = False

    # Iterate through the list
    for num in lst:
        # Check if the number is even
        if num % 2 == 0:
            even_product *= num
            has_even = True
        # Check if the number is odd
        else:
            odd_product *= num
            has_odd = True

    # Return the product of even and odd numbers
    if has_even:
        return even_product
    elif has_odd:
        return odd_product
    else:
