def find_Min_Swaps(arr, n):
    # Find the first occurrence of element that is out of order
    first = n
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            first = i

    # Find the last occurrence of element that is out of order
    last = 0
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            last = i

    # If the gap is less than 2, it's impossible to sort the array
    if last - first < 2:
        return -1

    # Calculate the minimum gap
    gap = last - first + 1

