def is_Isomorphic(str1, str2):
    """
    Checks if two strings are isomorphic to each other.

    Args:
    str1 (str): The first string to compare.
    str2 (str): The second string to compare.

    Returns:
    bool: True if the strings are isomorphic, False otherwise.
    """
    if len(str1) != len(str2):
        return False  # Not the same length

    # Create a dictionary to store the mapping between characters of str1 and str2
    char_map = {}

    # Iterate through both strings simultaneously
    for i in range(len(str1)):
        if str1[i] not in char_map:
            char_map[str1[i]] = str2[i]
        else:
            # If the character already exists in the dictionary, check if it's the same as the current character in str2
            if char_map[str1[i]] != str2[i]:
                return False
    return True

