def get_noOfways(grid):
    n = len(grid)
    # Create a 3D list to store the number of ways to tile each cell
    dp = [[[0 for _ in range(n)] for _ in range(n)] for _ in range(n)]

    # Base cases: one way to tile a single cell
    for i in range(n):
        dp[i][i][0] = 1
        dp[i][i][1] = 1

    # Fill the DP table
    for s in range(2, n+1):
        for i in range(n):
            for j in range(n):
                # Check all possible ways to tile the cell with one or two tiles
                for k in range(s):
                    dp[i][j][k+1] += dp[i][j][k]
                dp[i][j][s] += dp[i][j][s-1]

    # The number of ways to tile the entire grid
    return dp[0][0][n-1]

