def min_sum_path(triangle):
    """
    Given a triangle represented by a list of lists of integers, this function
    finds the minimum total path sum from top to bottom.

    Args:
    triangle (list of list of int): The triangle represented as a list of lists.

    Returns:
    int: The minimum total path sum.
    """
    if not triangle:
        return 0

    for row in range(1, len(triangle)):
        for col in range(len(triangle[row])):
            if col == 0:
                triangle[row][col] += triangle[row-1][col]
            elif col == len(triangle[row])-1:
                triangle[row][col] += triangle[row-1][col-1]
            else:
                triangle[row][col] += min(triangle[row-1][col], triangle[row-1][col-1])

    return min(triangle[-1])

